contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run deposits an amount (sent to fallback) and then attempts withdraw;
    // it asserts that if withdraw succeeded then the stored balance for this contract is zero,
    // and if withdraw reverted then the stored balance is unchanged from before the call.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        // deposit into c via fallback by sending Ether
        c.f{value: depositAmount}();

        // read balance recorded for this contract before withdraw
        uint256 before = c.balances(address(this));

        bool reverted;
        // attempt withdraw and capture whether it reverts
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = c.balances(address(this));

        // General rule:
        // - If withdraw succeeded (not reverted) then the stored balance for this contract must be zero.
        // - If withdraw reverted then the stored balance must remain equal to the value before the call.
        assert((!reverted && after == 0) || (reverted && after == before));
    }

    // allow receiving Ether in case withdraw sends Ether to this contract
    receive() external payable {}
}

