contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: deposit an amount into c via the fallback, then try to withdraw;
    // assert that if withdraw succeeds then c.balances[this] becomes zero and c's balance decreased by the deposited amount.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        // record c's balance before deposit
        uint256 cBalBefore = address(c).balance;
        // deposit into c by invoking its fallback with Ether
        // This is a top-level state-changing call: low-level call directly on c's address is not allowed by constraints,
        // so we invoke via calling c with empty calldata which triggers fallback and updates balances[msg.sender]
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent);

        // read recorded balance for this test contract after deposit
        uint256 balAfterDeposit = c.balances(address(this));

        bool didRevert;
        // attempt withdraw as a top-level call, capturing revert
        try c.withdraw() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 balAfterWithdraw = c.balances(address(this));
        uint256 cBalAfter = address(c).balance;

        // General rule asserted: if withdraw succeeded then recorded balance becomes zero and c's balance decreased by depositAmount;
        // otherwise (if withdraw reverted) the recorded balance is unchanged from after-deposit and c's balance did not decrease by depositAmount.
        assert((!didRevert && balAfterWithdraw == 0 && cBalBefore - cBalAfter == depositAmount) || (didRevert && balAfterWithdraw == balAfterDeposit && cBalAfter == cBalBefore));
    }

    // allow receiving Ether (not used here but present for completeness)
    receive() external payable {}
}

