contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will simulate arbitrary deposits from this contract into c by calling the fallback with value.
    // Then call withdraw and assert the invariant described in property_summary.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // record c and msg.sender (this contract) balances before interactions
        uint256 cBalBefore = address(c).balance;
        uint256 recordedBefore = c.balances(address(this));

        // perform a deposit to c by sending Ether to its fallback
        // this will increase c.balances[this] by depositAmount
        c.f{value: depositAmount}();

        uint256 recordedAfterDeposit = c.balances(address(this));
        uint256 cBalAfterDeposit = address(c).balance;

        // ensure the deposit had the expected observable effect: c's balance increased by depositAmount
        // and the per-address recorded balance increased by at most depositAmount (should increase exactly by depositAmount)
        // We don't assert here (only one assert at end), but we will use these values in the final assertion.

        // Now attempt withdraw and catch whether it reverted
        bool reverted;
        (bool success, ) = address(c).call(abi.encodeWithSelector(bytes4(keccak256("withdraw()"))));
        reverted = !success;

        uint256 recordedAfterWithdraw = c.balances(address(this));
        uint256 cBalAfterWithdraw = address(c).balance;
        uint256 thisBalAfter = address(this).balance;

        // General rule as a single assert:
        // If withdraw succeeded (not reverted) then the contract's recorded balance for this address must be 0
        // and c's Ether balance must have decreased by at least the amount that was recorded for this address after deposit.
        // If withdraw reverted then the recorded balance must be unchanged from after deposit and c's balance unchanged.
        assert(
            (!reverted && recordedAfterWithdraw == 0 && cBalAfterWithdraw + recordedAfterDeposit <= cBalAfterDeposit)
            || (reverted && recordedAfterWithdraw == recordedAfterDeposit && cBalAfterWithdraw == cBalAfterDeposit)
        );
    }

    receive() external payable { }
}

